using System.Globalization;
using System.Text.RegularExpressions;

namespace MedStorage.AiClient.Guardrails;

// Guardrail (Level 3): tool arguments are generated by the LLM and may be hallucinated or
// injected, so they are checked against strict rules before any REST call is made.
// Each method returns an error text for the model (it can then fix the call) or null when valid.
public static partial class ToolArgumentValidator
{
    public const int MaxQuantity = 100;
    private const int MaxShelfLifeYears = 10;

    // Letters (Latin/Cyrillic), digits, space and a few punctuation marks used in drug names
    [GeneratedRegex(@"^[\p{L}\d][\p{L}\d \-\.,'()/+%]{0,79}$")]
    private static partial Regex TradeNamePattern();

    public static string? ValidateTradeName(string? tradeName) =>
        string.IsNullOrWhiteSpace(tradeName) || !TradeNamePattern().IsMatch(tradeName.Trim())
            ? "Invalid tradeName: use 1-80 letters, digits, spaces or - . , ' ( ) / + %."
            : null;

    public static string? ValidateQuantity(int quantity) =>
        quantity is < 1 or > MaxQuantity ? $"Invalid quantity: must be between 1 and {MaxQuantity}." : null;

    public static bool TryParseExpiryDate(string? value, out DateOnly expiry, out string? error)
    {
        error = null;
        if (!DateOnly.TryParseExact(value?.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out expiry))
            error = "Invalid expiryDate: use format yyyy-MM-dd. Ask the user if the date is unknown, never invent it.";
        else if (expiry > DateOnly.FromDateTime(DateTime.UtcNow).AddYears(MaxShelfLifeYears))
            error = $"Invalid expiryDate: more than {MaxShelfLifeYears} years ahead looks like a typo, ask the user.";
        return error is null;
    }
}
